--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                                    NeoVim Options: https://neovim.io/doc/user/quickref/#option-list                                                                                                    │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                                      boolean (default off) global or local to buffer global-local                                                                                                      │
--    │                                                                               When on, Vim shows a completion menu as you type, similar to using i_CTRL-N, but triggered automatically.                                                                                │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.autocomplete = true

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                       When set to "dark" or "light", adjusts the default color groups for that background type.                                                                                        │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.background = "dark"

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                        Influences the working of <BS>, <Del>, CTRL-W and CTRL-U in Insert mode.  This is a list of items, separated by commas.                                                                         │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.backspace = "indent,eol,start"

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                                            This option is a list of comma-separated names.                                                                                                             │
--    │                                                                                                       unnamedplus	A variant of the "unnamed" flag which uses the                                                                                                       │
--    │                                                                                                             clipboard register "+" (quoteplus) instead of                                                                                                              │
--    │                                                                                                           register "*" for all yank, delete, change and put                                                                                                            │
--    │                                                                                                           operations which would normally go to the unnamed                                                                                                            │
--    │                                                                                                           register.  When "unnamed" is also included to the                                                                                                            │
--    │                                                                                                            option, yank and delete operations (but not put)                                                                                                            │
--    │                                                                                                             will additionally copy the text into register                                                                                                              │
--    │                                                                                                                          "*". See clipboard.                                                                                                                           │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.clipboard = "unnamedplus"

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                              A comma-separated list of options for Insert mode completion ins-completion.                                                                                              │
--    │                                                                                                    menu		Use a popup menu to show the possible completions.  The                                                                                                      │
--    │                                                                                                         menu is only shown when there is more than one match.                                                                                                          │
--    │                                                                                                                          ins-completion-menu                                                                                                                           │
--    │                                                                                                    menuone  	Use the popup menu also when there is only one match.                                                                                                    │
--    │                                                                                                         Useful when there is additional information about the                                                                                                          │
--    │                                                                                                                 match, e.g., what file it comes from.                                                                                                                  │
--    │                                                                                                  noinsert 	Do not insert any text for a match until the user selects                                                                                                  │
--    │                                                                                                         a match from the menu.  Only works in combination with                                                                                                         │
--    │                                                                                                        "menu" or "menuone". No effect if "longest" is present.                                                                                                         │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.completeopt = "menu,menuone,noinsert"

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │    When 'confirm' is on, certain operations that would normally fail because of unsaved changes to a buffer, e.g. ":q" and ":e", instead raise a dialog asking if you wish to save the current file(s).  You can still use a ! to unconditionally abandon a buffer.    │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.confirm = true

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                     In Insert mode: Use the appropriate number of spaces to insert a <Tab>.  Spaces are used in indents with the '>' and '<' commands and when 'autoindent' is on.  To insert a real tab when 'expandtab' is on, use CTRL-V<Tab>.                      │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.expandtab = true

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                              Ignore case in search patterns, cmdline-completion, when searching in the tags file, expr-== and for Insert-mode completion ins-completion.                                                               │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.ignorecase = true

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                           The value of this option influences when the last window will have a status line:                                                                                            │
--    │                                                                                                                                0: never                                                                                                                                │
--    │                                                                                                               1: only if there are at least two windows                                                                                                                │
--    │                                                                                                                               2: always                                                                                                                                │
--    │                                                                                                                   3: always and ONLY the last window                                                                                                                   │
--    │                                                                                                 Here "last window" means the last window in a column, i.e. the bottom-                                                                                                 │
--    │                                                                                                                 most one, just above the command line.                                                                                                                 │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.laststatus = 3

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                        Enables mouse support. For example, to enable the mouse in Normal mode and Visual mode:                                                                                         │
--    │                                                                                                           Mouse support can be enabled for different modes:                                                                                                            │
--    │                                                                                                                             n	Normal mode                                                                                                                              │
--    │                                                                                                                             v	Visual mode                                                                                                                              │
--    │                                                                                                                             i	Insert mode                                                                                                                              │
--    │                                                                                                                          c	Command-line mode                                                                                                                          │
--    │                                                                                                             h	all previous modes when editing a help file                                                                                                              │
--    │                                                                                                                          a	all previous modes                                                                                                                         │
--    │                                                                                                                 r	for hit-enter and more-prompt prompt                                                                                                                 │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.mouse = "a"

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                                              Print the line number in front of each line.                                                                                                              │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.number = true

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                           Enables pseudo-transparency for the popup-menu. Valid values are in 	the range of 0 for fully opaque popupmenu (disabled) to 100 for fully transparent background. Values between 0-30 are typically most useful.                           │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.pumblend = 25

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                           Maximum number of items to show in the popup menu (ins-completion-menu). Zero means "use available screen space".                                                                            │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.pumheight = 8

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                            Show the line number relative to the line with the cursor in front of each line.                                                                                            │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.relativenumber = true

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                                   Minimal number of screen lines to keep above and below the cursor.                                                                                                   │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.scrolloff = 3

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                        Round indent to multiple of 'shiftwidth'.  Applies to > and < commands.  CTRL-T and CTRL-D in Insert mode always round the indent to a multiple of 'shiftwidth' (this is Vi compatible).                                        │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.shiftround = true

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                                     Number of columns that make up one level of (auto)indentation.                                                                                                     │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.shiftwidth = 2

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                                  If in Insert, Replace or Visual mode put a message on the last line.                                                                                                  │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.showmode = false

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                              The minimal number of screen columns to keep to the left and to the right of the cursor if 'nowrap' is set.                                                                               │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.sidescrolloff = 8

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                                        When and how to draw the signcolumn.  Valid values are:                                                                                                         │
--    │                                                                                                             "auto"		only when there is a sign to display                                                                                                             │
--    │                                                                                                      "auto:[1-9]" 	resize to accommodate multiple signs up to the                                                                                                     │
--    │                                                                                                                given number (maximum 9), e.g. "auto:4"                                                                                                                 │
--    │                                                                                                                           "auto:[1-8]-[2-9]"                                                                                                                           │
--    │                                                                                                             resize to accommodate multiple signs up to the                                                                                                             │
--    │                                                                                                             given maximum number (maximum 9) while keeping                                                                                                             │
--    │                                                                                                              at least the given minimum (maximum 8) fixed                                                                                                              │
--    │                                                                                                            space. The minimum number should always be less                                                                                                             │
--    │                                                                                                                than the maximum number, e.g. "auto:2-5"                                                                                                                │
--    │                                                                                                                             "no"		never                                                                                                                              │
--    │                                                                                                                             "yes"		always                                                                                                                             │
--    │                                                                                                    "yes:[1-9]" 	always, with fixed space for signs up to the given                                                                                                     │
--    │                                                                                                                    number (maximum 9), e.g. "yes:3"                                                                                                                    │
--    │                                                                                                     "number"	display signs in the 'number' column.  If the number                                                                                                     │
--    │                                                                                                            column is not present, then behaves like "auto".                                                                                                            │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.signcolumn = "yes"

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                         Override the 'ignorecase' option if the search pattern contains upper case characters.                                                                                         │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.smartcase = true

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                         Do smart autoindenting when starting a new line.  Works for C-like programs, but can also be used for other languages.                                                                         │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.smartindent = true

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                    When enabled, the <Tab> key will indent by 'shiftwidth' if the cursor is in leading whitespace.                                                                                     │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.smarttab = true

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                                  Create soft tab stops, separated by 'softtabstop' number of columns.                                                                                                  │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.softtabstop = 2

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                           When on, splitting a window will put the new window below the current one. :split                                                                                            │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.splitbelow = true

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                              The value of this option determines the scroll behavior when opening, closing or resizing horizontal splits.                                                                              │
--    │                                                                                                                          Possible values are:                                                                                                                          │
--    │                                                                                                           cursor		Keep the same relative cursor position.                                                                                                            │
--    │                                                                                                            screen		Keep the text on the same screen line.                                                                                                             │
--    │                                                                                                                  topline		Keep the topline the same.                                                                                                                 │
--    │                                                                                                   For the "screen" and "topline" values, the cursor position will be                                                                                                   │
--    │                                                                                                 changed when necessary.  In this case, the jumplist will be populated                                                                                                  │
--    │                                                                                                   with the previous cursor position.  For "screen", the text cannot                                                                                                    │
--    │                                                                                                     always be kept on the same screen line when 'wrap' is enabled.                                                                                                     │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.splitkeep = "screen"

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                         When on, splitting a window will put the new window right of the current one. :vsplit                                                                                          │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.splitright = true

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                       Use a swap-file for the buffer (if 'updatecount' is non-zero). The 'directory' option decides where swapfiles are stored.                                                                        │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.swapfile = false

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                               Defines the column multiple used to display the Horizontal Tab character (ASCII 9); a Horizontal Tab always advances to the next tab stop.                                                               │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.tabstop = 2

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                        Enables 24-bit RGB color in the TUI.  Uses "gui" :highlight attributes instead of "cterm" attributes. guifg Requires an ISO-8613-3 compatible terminal.                                                         │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.termguicolors = true

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                                    Time in milliseconds to wait for a mapped sequence to complete.                                                                                                     │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.timeoutlen = 300

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                                                    If enabled, Nvim will update the (GUI or terminal) window title.                                                                                                    │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.title = true

--    ╭────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╮
--    │                                                                            This option changes how text is displayed.  It doesn't change the text in the buffer, see 'textwidth' for that.                                                                             │
--    ╰────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────╯

vim.o.wrap = false
